$ErrorActionPreference='Stop'
$root=$PSScriptRoot;$dir="$root/bo-sung-1";$utf8=New-Object System.Text.UTF8Encoding($false)
$bins=Get-Content -Raw -Encoding UTF8 "$dir/buoc-tai.json"|ConvertFrom-Json
$step=Get-Content -Raw -Encoding UTF8 "$root/out/l1step20261113a/analysis.json"|ConvertFrom-Json
$pilotTag='l1maint20261113a'
if(Test-Path "$root/out/l1maint20261113b/analysis.json"){$pilotTag='l1maint20261113b'}
$pilot=Get-Content -Raw -Encoding UTF8 "$root/out/$pilotTag/analysis.json"|ConvertFrom-Json
$initialPilot=Get-Content -Raw -Encoding UTF8 "$root/out/l1maint20261113a/analysis.json"|ConvertFrom-Json
$order=Get-Content -Raw -Encoding UTF8 "$dir/giao-dich-sau-bao-tri.json"|ConvertFrom-Json
$table=($bins.rows30s|ForEach-Object {"| $($_.fromSeconds)-$($_.toSeconds) | $($_.k6Sent) | $([Math]::Round($_.k6SentPerSecond,4)) | $($_.k6Completed) | $([Math]::Round($_.k6CompletedPerSecond,4)) | $($_.gatewayCompleted) | $([Math]::Round($_.gatewayCompletedPerSecond,4)) | $($_.gatewayMatched) | $([Math]::Round($_.gatewayMatchedPerSecond,4)) | $($_.gatewayOther) |"})-join "`n"
$capacity=if(!$step.totals.dropped_iterations -and !$step.totals.journey_failed){'Trong lượt khỏe đã kiểm, maxVUs=20 mỗi scenario không gây dropped hoặc lỗi hành trình. Đây là kết quả ở mức tải/thời gian này, không bảo đảm đủ cho mọi lỗi hoặc chu kỳ dài.'}else{'Lượt kiểm có dropped hoặc lỗi hành trình; không nhận là maxVUs=20 đủ. Xem counter và lỗi chi tiết trước khi điều phối chọn cấu hình.'}
$values=@{'@EPOCH@'=$bins.testEpochUtc;'@BINS@'=$table;'@TAIL@'=($bins.tailOutsideConfiguredWindow|ConvertTo-Json -Compress);'@MATCH@'="k6=$($step.totals.route_responses), gateway=$($step.gateway.total), missing=$($step.gateway.missing.Count), mismatch=$($step.gateway.mismatches.Count), extra=$($step.gateway.extraRequests.Count)";'@STARTS@'=($bins.journeyStartsByScenario|ConvertTo-Json -Compress);'@COUNTS@'=($bins.counts|ConvertTo-Json -Compress);'@PEAK@'=($bins.observedPeakActiveJourneysByScenario|ConvertTo-Json -Compress);'@PEAK_ALL@'=[string]$bins.observedPeakActiveJourneysTotal;'@VU_GAUGE@'=[string]$bins.k6MaxVUsGauge;'@CAPACITY@'=$capacity}
$text=[IO.File]::ReadAllText("$dir/buoc-tai-template.md");foreach($k in $values.Keys){$text=$text.Replace($k,$values[$k])};[IO.File]::WriteAllText("$dir/buoc-tai.md",$text,$utf8)
$values=@{'@UTC@'=[DateTime]::UtcNow.ToString('o');'@PURCHASE@'="orderId $($order.orderId), final $($order.states[-1].state), $($order.tickets.tickets.Count) ticket(s), ticket state $($order.tickets.tickets[0].state)";'@STATES@'=(($order.states|ForEach-Object {$_.state})-join ' -> ');'@CALLBACK@'=($order.callback|ConvertTo-Json -Depth 8 -Compress);'@PILOT@'="$($pilot.totals.journey_started) journeys, $($pilot.journeys.journey_finished.purchase) purchases completed, $($pilot.totals.route_responses) gateway requests; failed=$([int]$pilot.totals.journey_failed), dropped=$([int]$pilot.totals.dropped_iterations), 401=$([int]$pilot.totals.gateway_401), refresh failed=$([int]$pilot.totals.token_refresh_failure); gateway missing=$($pilot.gateway.missing.Count), mismatch=$($pilot.gateway.mismatches.Count), extra=$($pilot.gateway.extraRequests.Count)";'@STEP@'=$capacity;'@DURABILITY@'='Bằng chứng ở phuc-hoi-remote-ssh.json, phuc-hoi-mock.json và tunnel-independent-launcher-proof.json; phép kiểm no-shell ở gioi-han-tunnel.json; không đồng nhất kiểm PID cũ với độ bền qua phiên.'}
$values['@PILOT_TAG@']=$pilotTag
$values['@INITIAL_PILOT@']="Pilot ban dau l1maint20261113a: $($initialPilot.totals.journey_started) journeys, $($initialPilot.journeys.journey_finished.purchase)/$($initialPilot.journeys.journey_started.purchase) purchases completed; $($initialPilot.totals.journey_failed) create-payment failures (19x504 + 14x503). No dropped/401 from k6; original raw/log/trace retained. Subsequent stepped run clean; one additional standard pilot planned before dispatch in bo-sung-1/ke-hoach-kiem-lai-pilot.json. Cause of initial 503/504 remains OPEN; current clean window does not erase it."
$text=[IO.File]::ReadAllText("$dir/BAN-GIAO-3-template.md");foreach($k in $values.Keys){$text=$text.Replace($k,$values[$k])}
$destination=if($pilotTag -eq 'l1maint20261113b'){"$root/BAN-GIAO-3-sau-bao-tri.md"}else{"$dir/BAN-GIAO-3-ban-tam.md"}
[IO.File]::WriteAllText($destination,$text,$utf8)
$capacity
Get-Content -Encoding UTF8 "$dir/buoc-tai.md" -TotalCount 25
